/**
 * Shared types and helpers for Retab primitive viewers.
 *
 * These mirror the result shapes returned by the Retab API for the six core
 * primitives (parse, extraction, edit, classification, partition, split).
 * The viewers are headless: they take one of these typed result objects as a
 * prop and never fetch anything themselves. Resolving a source document (for
 * the overlay viewers) goes through the optional `ViewerAdapter`.
 */

// ---------------------------------------------------------------------------
// Shared envelope
// ---------------------------------------------------------------------------

export type PrimitiveStatus =
  | "pending"
  | "queued"
  | "in_progress"
  | "completed"
  | "failed"
  | "cancelled"

export interface FileRef {
  id: string
  filename: string
  mime_type: string
}

export interface PrimitiveError {
  code: string
  message: string
  details?: Record<string, unknown> | null
}

export interface RetabUsage {
  credits: number
}

export interface PrimitiveResult<TOutput> {
  id: string
  file: FileRef
  model: string
  instructions?: string | null
  output: TOutput
  status: PrimitiveStatus
  error?: PrimitiveError | null
  usage?: RetabUsage | null
  created_at?: string | null
}

/** Resolves the things a viewer can't derive from the result alone. */
export interface ViewerAdapter {
  /** Resolve a FileRef to a URL a document surface can render. */
  getDocumentUrl?: (file: FileRef) => string | Promise<string>
  /** Extraction-only: lazily fetch field-level source grounding. */
  getExtractionSources?: (extractionId: string) => Promise<ExtractionSources>
}

// ---------------------------------------------------------------------------
// Parse
// ---------------------------------------------------------------------------

export interface ParseOutput {
  /** Per-page text, 1-indexed and ordered. */
  pages: string[]
  /** Full concatenated document text. */
  text: string
}

export interface Parse extends PrimitiveResult<ParseOutput> {
  table_parsing_format?: string
  image_resolution_dpi?: number
}

// ---------------------------------------------------------------------------
// Extraction
// ---------------------------------------------------------------------------

export type ExtractionOutput = Record<string, unknown>

export interface ExtractionConsensus {
  choices: ExtractionOutput[]
  likelihoods?: Record<string, unknown> | null
}

export interface Extraction extends PrimitiveResult<ExtractionOutput> {
  json_schema: Record<string, unknown>
  n_consensus?: number
  consensus?: ExtractionConsensus | null
}

/** A leaf in an `ExtractionSources` tree: the value plus where it came from. */
export interface ExtractionSourceLeaf {
  value: unknown
  source?: {
    content?: string
    /** Normalized bbox for PDF/image sources. */
    bbox?: BBox
    /** Cell reference for spreadsheet sources, e.g. "Sheet1!B4". */
    cell?: string
    /** Character span for plain-text sources. */
    span?: { start: number; end: number }
  } | null
}

export interface ExtractionSources {
  extraction_id: string
  document_type: "pdf" | "image" | "csv" | "xlsx" | "docx" | "txt"
  file: FileRef
  extraction: ExtractionOutput
  /** Same shape as `extraction`, but every leaf is an `ExtractionSourceLeaf`. */
  sources: Record<string, unknown>
}

// ---------------------------------------------------------------------------
// Classification
// ---------------------------------------------------------------------------

export interface Category {
  name: string
  handle_key?: string | null
  description: string
}

export interface ClassificationDecision {
  category: string
  reasoning: string
}

export interface ClassificationConsensus {
  choices: ClassificationDecision[]
  /** Agreement of the winning category in [0, 1]. */
  likelihoods: number
}

export interface Classification extends PrimitiveResult<ClassificationDecision | null> {
  categories: Category[]
  n_consensus?: number
  consensus?: ClassificationConsensus | null
}

// ---------------------------------------------------------------------------
// Edit
// ---------------------------------------------------------------------------

/** Normalized bounding box. left/top/width/height are 0..1; page is 1-based. */
export interface BBox {
  left: number
  top: number
  width: number
  height: number
  page: number
}

export type FieldType = "text" | "checkbox"

export interface FormField {
  key: string
  bbox: BBox
  type: FieldType
  description: string
  value: string | null
}

export interface MIMEData {
  filename?: string
  mime_type?: string
  /** base64 data URL of the filled document. */
  url?: string
}

export interface EditResult {
  form_data: FormField[]
  filled_document: MIMEData
}

export interface EditConfig {
  color: string
}

export interface Edit extends PrimitiveResult<EditResult | null> {
  config?: EditConfig
  template_id?: string | null
  filled_document_ref?: FileRef | null
}

// ---------------------------------------------------------------------------
// Partition
// ---------------------------------------------------------------------------

export interface PartitionChunk {
  /** The partition key value for this chunk, e.g. "Chapter 1" or "INV-12345". */
  key: string
  /** 1-indexed pages assigned to this chunk. */
  pages: number[]
}

export interface PartitionConsensus {
  choices: PartitionChunk[][]
  likelihoods: { key: number | null; pages: number[] }[]
}

export interface Partition extends PrimitiveResult<PartitionChunk[] | null> {
  key: string
  allow_overlap?: boolean
  n_consensus?: number
  consensus?: PartitionConsensus | null
}

// ---------------------------------------------------------------------------
// Split
// ---------------------------------------------------------------------------

export interface Subdocument {
  name: string
  description: string
  allow_multiple_instances?: boolean
}

export interface SplitResult {
  /** Subdocument name, e.g. "cover letter". */
  name: string
  /** 1-indexed pages assigned to this subdocument. */
  pages: number[]
}

export interface SplitConsensus {
  choices: SplitResult[][]
  likelihoods: { name: number | null; pages: number[] }[]
}

export interface Split extends PrimitiveResult<SplitResult[] | null> {
  subdocuments: Subdocument[]
  n_consensus?: number
  consensus?: SplitConsensus | null
}

// ---------------------------------------------------------------------------
// Shared view-model helpers (pure, no React)
// ---------------------------------------------------------------------------

/** A contiguous group of pages assigned to one named/keyed segment. */
export interface PageGroup {
  label: string
  pages: number[]
  /** Stable index into the original chunk list (for color assignment). */
  index: number
}

/** Normalize partition/split output into a common `PageGroup[]`. */
export function toPageGroups(
  output:
    | { key: string; pages: number[] }[]
    | { name: string; pages: number[] }[]
    | null
    | undefined
): PageGroup[] {
  if (!output) return []
  return output.map((segment, index) => ({
    label: "key" in segment ? segment.key : segment.name,
    pages: [...segment.pages].sort((a, b) => a - b),
    index,
  }))
}

/** Total page count implied by a set of page groups (max page seen). */
export function pageCountFromGroups(groups: PageGroup[]): number {
  let max = 0
  for (const g of groups) {
    for (const p of g.pages) max = Math.max(max, p)
  }
  return max
}

/** Format a sorted page list as compact ranges, e.g. [1,2,3,5] -> "1–3, 5". */
export function formatPageRanges(pages: number[]): string {
  if (pages.length === 0) return "—"
  const sorted = [...pages].sort((a, b) => a - b)
  const ranges: string[] = []
  let start = sorted[0]
  let prev = sorted[0]
  for (let i = 1; i <= sorted.length; i++) {
    const cur = sorted[i]
    if (cur === prev + 1) {
      prev = cur
      continue
    }
    ranges.push(start === prev ? `${start}` : `${start}–${prev}`)
    start = cur
    prev = cur
  }
  return ranges.join(", ")
}

/** Map a likelihood in [0,1] to a coarse confidence bucket. */
export type ConfidenceLevel = "high" | "medium" | "low"

export function confidenceLevel(likelihood: number | null | undefined): ConfidenceLevel | null {
  if (likelihood == null) return null
  if (likelihood >= 0.8) return "high"
  if (likelihood >= 0.5) return "medium"
  return "low"
}

/** A small palette of hues for assigning distinct colors to page groups. */
export const PAGE_GROUP_HUES = [205, 145, 35, 280, 0, 175, 320, 95] as const

export function hueForIndex(index: number): number {
  return PAGE_GROUP_HUES[index % PAGE_GROUP_HUES.length]
}
